import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { checkpoint, restore } from "@tigrisdata/agent-kit";
import { removeBucket } from "@tigrisdata/storage";
import * as fs from "fs";

async function main() {
  const s3 = new S3Client({
    region: "REDACTED",
    endpoint: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!
    }
  });

  const sourceBucket = "pipeline-state";

  // 1. Upload v1
  await s3.send(new PutObjectCommand({
    Bucket: sourceBucket,
    Key: "v1.txt",
    Body: "version=1"
  }));

  // 2. Checkpoint
  const { data: ckpt, error: ckptError } = await checkpoint(sourceBucket, { name: "before-mutation" });
  if (ckptError) {
    console.error("Failed to create checkpoint:", ckptError);
    process.exit(1);
  }

  // 3. Mutate
  await s3.send(new PutObjectCommand({
    Bucket: sourceBucket,
    Key: "v1.txt",
    Body: "version=2"
  }));

  // 4. Restore
  const { data: restored, error: restoreError } = await restore(sourceBucket, ckpt!.snapshotId, { forkName: "rollback-recovery" });
  if (restoreError) {
    console.error("Failed to restore checkpoint:", restoreError);
    process.exit(1);
  }

  const recoveryBucket = restored!.bucket;
  fs.writeFileSync("/home/user/chained-ckpt/recovery.json", JSON.stringify({ recoveryBucket }));

  // 5. Teardown
  const { error: removeError } = await removeBucket(recoveryBucket, { force: true });
  if (removeError) {
    console.error("Failed to remove recovery bucket:", removeError);
    process.exit(1);
  }

  process.exit(0);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

